// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Actor actor;

    function setUp() public {
        c = new ReentrancyDAO();
        actor = new Actor(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(actor), amount);

        // first deposit + withdrawal: caller has credit > 0, both versions succeed
        actor.deposit(amount);
        actor.withdraw();

        // second withdrawal: caller has zero credit.
        // C: guard oCredit>0 skips the branch, no external call, succeeds.
        // Mutant: guard oCredit>=0 forces a zero-value call to the caller,
        // and the Actor reverts on zero-value payments, so it reverts.
        bool ok;
        try actor.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "withdrawAll must succeed for a caller with zero credit");
    }
}

contract Actor {
    ReentrancyDAO public immutable c;

    constructor(ReentrancyDAO c_) {
        c = c_;
    }

    function deposit(uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function withdraw() external {
        c.withdrawAll();
    }

    // Accepts payments only when value > 0; reverts on zero-value pushes.
    fallback() external payable {
        if (msg.value == 0) revert();
    }
}
